<?php
$value = static function (string $key) use ($permit) {
    $current = old($key, $permit[$key] ?? '');
    if (in_array($key, ['fecha_inicio', 'fecha_fin'], true) && $current !== '') {
        $timestamp = strtotime((string) $current);
        return $timestamp === false ? $current : date('Y-m-d\TH:i', $timestamp);
    }
    return $current;
};
$typeLabels = ['Electrico' => 'Eléctrico', 'Excavacion' => 'Excavación'];
